<?php require 'layout.php'; userStart('Checkout',''); ?><div class="container"><div class="page-head"><span class="eyebrow">SECURE CHECKOUT</span><h1>Complete your order</h1><p>Confirm delivery details, coupon and delivery preference.</p></div><div class="two-col"><div class="form-card" style="max-width:none;margin:0"><form data-validate onsubmit="placeDemoOrder(event)" novalidate><div class="form-grid"><div class="form-group"><label>Full Name *</label><input name="full_name" class="form-control" data-validation="required|alpha|min|max" data-min="2" data-max="80" required></div><div class="form-group"><label>Mobile *</label><input name="mobile" class="form-control" data-validation="required|numeric|min|max" data-min="10" data-max="10" required></div><div class="form-group full"><label>Address *</label><textarea name="address" class="form-control" data-validation="required|min|max" data-min="5" data-max="250" required rows="4"></textarea></div><div class="form-group"><label>City *</label><input name="city" class="form-control" data-validation="required|alpha|min|max" data-min="2" data-max="50" required></div><div class="form-group"><label>Pincode *</label><input name="pincode" class="form-control" data-validation="required|numeric|min|max" data-min="6" data-max="6" required></div><div class="form-group full"><label>Coupon Code</label><div style="display:flex;gap:8px"><input id="couponInput" name="coupon" placeholder="Try WELCOME10"><button type="button" class="btn" onclick="applyCoupon()">Apply</button></div><small id="couponMessage" class="muted"></small></div><div class="form-group"><label>Delivery Service *</label><select id="deliveryType" name="delivery" required data-validation="required"><option value="">Choose delivery</option><option value="standard">Standard Home Delivery · Free above ₹999</option><option value="urgent">Urgent / Priority Delivery · ₹149</option></select></div><div class="form-group"><label>Payment Method *</label><select name="payment_method" required data-validation="required"><option value="">Select payment</option><option>Cash on Delivery</option><option>Online Payment (Demo)</option></select></div></div><div class="card" style="background:#f7fbfb;margin:8px 0 18px"><strong><i class="bi bi-shield-check"></i> Demo checkout</strong><p style="color:var(--muted);font-size:12px;margin-top:4px">No real payment is processed. This is a static frontend interaction.</p></div><button class="btn primary" type="submit">Place Demo Order <i class="bi bi-check2-circle"></i></button></form></div><div class="summary"><h3>Order Summary</h3><div><span>Items</span><strong id="summaryItems">0</strong></div><div><span>Subtotal</span><strong id="summarySubtotal">₹0</strong></div><div><span>Delivery</span><strong id="summaryDelivery">₹0</strong></div><div><span>Discount</span><strong id="summaryDiscount">₹0</strong></div><div class="total"><span>Total</span><strong id="summaryTotal">₹0</strong></div><hr style="margin:18px 0;border:0;border-top:1px solid var(--border)"><p style="font-size:12px;color:var(--muted)"><i class="bi bi-info-circle"></i> Free standard delivery applies to orders above ₹999.</p></div></div></div><script>
let appliedDiscount=0;function applyCoupon(){const c=(document.getElementById('couponInput').value||'').trim().toUpperCase();const msg=document.getElementById('couponMessage');appliedDiscount=c==='WELCOME10'?Math.min(getSubtotal()*.10,200):c==='HEALTH150'&&getSubtotal()>=1499?150:0;msg.textContent=appliedDiscount?'Coupon applied: ₹'+appliedDiscount+' saved.':'Invalid or ineligible coupon for this demo.';msg.style.color=appliedDiscount?'var(--success)':'var(--danger)';renderSummary()}function getSubtotal(){return getCart().reduce((s,p)=>s+p.price*p.qty,0)}function renderSummary(){const sub=getSubtotal(),items=getCart().reduce((s,p)=>s+p.qty,0),urgent=document.getElementById('deliveryType')?.value==='urgent',delivery=urgent?149:(sub>=999||sub===0?0:50),total=Math.max(0,sub+delivery-appliedDiscount);document.getElementById('summaryItems').textContent=items;document.getElementById('summarySubtotal').textContent='₹'+sub;document.getElementById('summaryDelivery').textContent='₹'+delivery;document.getElementById('summaryDiscount').textContent='- ₹'+appliedDiscount;document.getElementById('summaryTotal').textContent='₹'+total}function placeDemoOrder(e){e.preventDefault();localStorage.removeItem('surgical_cart');location.href='order_success.php'}document.addEventListener('DOMContentLoaded',()=>{renderSummary();document.getElementById('deliveryType').addEventListener('change',renderSummary)})</script><?php userEnd(); ?>
